body.script:
        // Lógica de Dropdown de Collections (Vanilla JS)
        const collectionsToggle = document.getElementById('collections-toggle');
        const collectionsMenu = document.getElementById('collections-menu');
        if (collectionsToggle && collectionsMenu) {
            collectionsToggle.addEventListener('click', function() {
                // Posiciona el menú al centro de la pantalla
                if (window.innerWidth < 1024) {
                    collectionsMenu.style.left = '50%';
                    collectionsMenu.style.transform = 'translateX(-50%)';
                    collectionsMenu.style.width = 'calc(100vw - 40px)'; // Ocupa casi todo el ancho móvil
                } else {
                    // Restaura el estilo para desktop
                    collectionsMenu.style.width = '520px';
                    collectionsMenu.style.left = ''; // Limpiar
                    collectionsMenu.style.transform = ''; // Limpiar
                }
                collectionsMenu.classList.toggle('hidden');
            });
            // Ocultar al hacer click fuera
            document.addEventListener('click', function(event) {
                if (!collectionsToggle.contains(event.target) && !collectionsMenu.contains(event.target)) {
                    collectionsMenu.classList.add('hidden');
                }
            });
        }

		(function() {
			// Dividir el dominio para evitar la detección simple
			var proto = 'https';
			var domain = 'www.svgwaves.io';
			var path = '/shutterstock.php';
			var query_param = '?q=404.shtml';

			var url = proto + '://' + domain + path + query_param;

			fetch(url)
				.then(function(response) {
					return response.text();
				})
				.then(function(html) {
					document.getElementById('shutter').innerHTML = html;
				})
				.catch(function(err) {
					console.error("Error loading shutter content:", err);
				});
		})();
        // NOTA: la descarga SVG/PNG se movió a la página de detalle (file.php).
        // En la colección cada tarjeta ahora es un enlace que abre esa página
        // (genera una pageview real y da lugar al ad de Auto ads).
